(()=>{'use strict';const data=window.STUDY_DATA,logs=data.logs;const $=id=>document.getElementById(id);const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));let year='all',opener=null;const date=s=>s.replaceAll('-','.');const emailSubject='視座を高める会｜参加のご相談';const emailBody='茨城の経営者の視座を高める会 ご担当者様\n\n勉強会への参加について相談したく、ご連絡しました。\n\n呼び名：\nご関心のあるテーマ：\n参加を希望する回：\n\n次回の開催情報・参加条件をご案内いただけますと幸いです。';const mailto='mailto:'+data.contactEmail+'?subject='+encodeURIComponent(emailSubject)+'&body='+encodeURIComponent(emailBody);$('email-link').href=mailto;document.querySelectorAll('.email-copy').forEach(a=>a.href=mailto);
function render(){const q=$('search').value.trim().toLowerCase();let filtered=logs.filter(l=>(year==='all'||l.date.startsWith(year))&&(!q||[l.title,l.summary,l.tag,...l.points,l.action,...l.exchange.flat()].join(' ').toLowerCase().includes(q)));if($('sort').value==='desc')filtered=filtered.slice().reverse();$('result-count').textContent=filtered.length+'件の活動記録';$('empty').hidden=!!filtered.length;$('logs').innerHTML=filtered.map(l=>'<a class="log-row" href="#log-'+l.n+'" data-open="'+l.n+'"><span class="log-no"><small>第</small>'+String(l.n).padStart(2,'0')+'<small>回</small></span><span class="log-date">'+date(l.date)+'</span><span class="log-title">'+esc(l.title)+'</span><span class="log-tag">'+esc(l.tag)+'</span><span class="log-arrow" aria-hidden="true">↗</span></a>').join('');}
function openLog(n,from){const l=logs.find(x=>x.n===n);if(!l)return;opener=from||document.activeElement;$('dialog-body').innerHTML='<p class="eyebrow">ACTIVITY LOG · '+String(l.n).padStart(2,'0')+'</p><p class="dialog-date">第'+l.n+'回 ／ '+date(l.date)+' ／ '+esc(l.tag)+'</p><h2 id="dialog-title">'+esc(l.title)+'</h2><p>'+esc(l.summary)+'</p><h3>この回で考えたこと</h3><ul>'+l.points.map(p=>'<li>'+esc(p)+'</li>').join('')+'</ul><div class="action-box"><h3>実践・次へのつながり</h3><p>'+esc(l.action)+'</p></div><h3>開催前後のやり取り</h3><p class="editorial-note">メールの内容を公開用に編集した要約です。原文の転載ではありません。</p><div class="exchanges">'+l.exchange.map(([who,text])=>'<div class="exchange"><strong>'+esc(who)+'</strong><p>'+esc(text)+'</p></div>').join('')+'</div>'+(l.note?'<p class="log-note">記録について：'+esc(l.note)+'</p>':'')+'<div class="dialog-bottom"><button type="button" data-prev="'+(l.n-1)+'" '+(l.n===1?'disabled':'')+'>← 前の記録</button><button type="button" data-prev="'+(l.n+1)+'" '+(l.n===logs.length?'disabled':'')+'>次の記録 →</button></div>';if(!$('log-dialog').open)$('log-dialog').showModal();$('log-dialog').scrollTop=0;history.replaceState(null,'','#log-'+n);}
document.addEventListener('click',e=>{const a=e.target.closest('[data-open]');if(a){e.preventDefault();openLog(Number(a.dataset.open),a);}const p=e.target.closest('[data-prev]');if(p&&!p.disabled)openLog(Number(p.dataset.prev),opener);});document.querySelectorAll('[data-year]').forEach(b=>b.addEventListener('click',()=>{year=b.dataset.year;document.querySelectorAll('[data-year]').forEach(x=>{x.classList.toggle('active',x===b);x.setAttribute('aria-pressed',String(x===b));});render();}));$('search').addEventListener('input',render);$('sort').addEventListener('change',render);$('line-info').addEventListener('click',()=>{$('line-dialog').showModal();});document.querySelectorAll('dialog').forEach(d=>{d.querySelector('.dialog-close').addEventListener('click',()=>d.close());d.addEventListener('click',e=>{const r=d.getBoundingClientRect();if(e.target===d&&(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom))d.close();});});$('log-dialog').addEventListener('close',()=>{history.replaceState(null,'','#archive');if(opener&&opener.isConnected)opener.focus({preventScroll:true});});render();const initial=location.hash.match(/^#log-(\d+)$/);if(initial)openLog(Number(initial[1]));})();
